Here is the interface:
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BatchErrorFileProcessingOperation {
    LogErrors,
    RetryFailedRequests,
}


#[derive(Debug,Copy,Clone,PartialEq,Eq,Hash)]
pub enum BatchFileTripleReconciliationOperation {
    EnsureInputRequestIdsMatchErrorRequestIds,
    CheckForBatchErrorFileOnline,
    CheckForBatchOutputAndErrorFileOnline,
    DownloadBatchOutputAndMaybeErrorFileOnline,
    DownloadBatchOutputFileOnline,
    EnsureInputRequestIdsMatchOutputRequestIds,
    EnsureInputRequestIdsMatchOutputRequestIdsCombinedWithErrorRequestIds,
    MoveBatchInputAndErrorToTheDoneDirectory,
    MoveBatchInputAndOutputToTheDoneDirectory,
    MoveBatchTripleToTheDoneDirectory,
    ProcessBatchErrorFile,
    ProcessBatchOutputFile,
    RecalculateRecommendedCourseOfActionIfTripleChanged,
}

/// Trait describing how a `BatchFileTriple` can be reconciled if unprocessed.
#[async_trait]
pub trait ReconcileUnprocessed<E> {
    async fn reconcile_unprocessed(&mut self, client: &dyn LanguageModelClientInterface<E>, expected_content_type: &ExpectedContentType, process_output_file_fn: &BatchWorkflowProcessOutputFileFn, process_error_file_fn: &BatchWorkflowProcessErrorFileFn) -> Result<(), E>;
}


pub trait RecalculateRecommendedActions {
    fn recalculate_recommended_actions(&self) -> Result<BatchFileReconciliationRecommendedCourseOfAction, BatchReconciliationError>;
}


#[async_trait]
pub trait ExecuteReconciliationOperation<E> {
    async fn execute_reconciliation_operation(&mut self, client: &dyn LanguageModelClientInterface<E>, operation: &BatchFileTripleReconciliationOperation, expected_content_type: &ExpectedContentType, process_output_file_fn: &BatchWorkflowProcessOutputFileFn, process_error_file_fn: &BatchWorkflowProcessErrorFileFn) -> Result<Option<BatchFileReconciliationRecommendedCourseOfAction>, E>;
}

pub type BatchWorkflowProcessOutputFileFn = for<'a> fn(
    &'a BatchFileTriple,
    &'a (dyn BatchWorkspaceInterface + 'a),
    &'a ExpectedContentType,
) -> Pin<Box<dyn Future<Output = Result<(), BatchOutputProcessingError>> + Send + 'a>>;


pub type BatchWorkflowProcessErrorFileFn = for<'a> fn(
    &'a BatchFileTriple,
    &'a [BatchErrorFileProcessingOperation],
) -> Pin<Box<dyn Future<Output = Result<(), BatchErrorProcessingError>> + Send + 'a>>;

#[derive(Debug,Clone,PartialEq,Eq)]
pub struct BatchFileReconciliationRecommendedCourseOfAction {
    steps: Vec<BatchFileTripleReconciliationOperation>,
}

impl<E> ExecuteReconciliationOperation<E> for BatchFileTriple where E : From<BatchReconciliationError> + From<BatchDownloadError> + From<OpenAIClientError> + From<BatchMetadataError> + From<std::io::Error> + From<FileMoveError> + From<BatchOutputProcessingError> + From<BatchErrorProcessingError> + From<BatchValidationError> + Debug {
    async fn execute_reconciliation_operation(&mut self, client: &dyn LanguageModelClientInterface<E>, operation: &BatchFileTripleReconciliationOperation, expected_content_type: &ExpectedContentType, process_output_file_fn: &BatchWorkflowProcessOutputFileFn, process_error_file_fn: &BatchWorkflowProcessErrorFileFn) -> Result<Option<BatchFileReconciliationRecommendedCourseOfAction>, E> {
        info!(
            "Preparing to execute reconciliation operation {:?} for batch {:?}",
            operation,
            self.index()
        );

        let workspace = self.workspace();
        let mut new_recommended_actions = None;

        use BatchFileTripleReconciliationOperation::*;

        match operation {
            EnsureInputRequestIdsMatchErrorRequestIds => {
                self.ensure_input_matches_error().await?;
            }
            EnsureInputRequestIdsMatchOutputRequestIds => {
                self.ensure_input_matches_output().await?;
            }
            EnsureInputRequestIdsMatchOutputRequestIdsCombinedWithErrorRequestIds => {
                self.ensure_input_matches_output_and_error().await?;
            }
            ProcessBatchErrorFile => {
                let operations = vec![
                    BatchErrorFileProcessingOperation::LogErrors,
                    BatchErrorFileProcessingOperation::RetryFailedRequests,
                ];
                process_error_file_fn(self, &operations).await?;
            }
            ProcessBatchOutputFile => {
                process_output_file_fn(self, &**workspace, expected_content_type).await?;
            }
            MoveBatchInputAndErrorToTheDoneDirectory => {
                self.move_input_and_error_to_done().await?;
            }
            MoveBatchInputAndOutputToTheDoneDirectory => {
                self.move_input_and_output_to_done().await?;
            }
            MoveBatchTripleToTheDoneDirectory => {
                self.move_all_to_done().await?;
            }
            CheckForBatchOutputAndErrorFileOnline => {
                self.check_for_and_download_output_and_error_online(client).await?;
                new_recommended_actions = Some(self.recalculate_recommended_actions()?);
            }
            RecalculateRecommendedCourseOfActionIfTripleChanged => {
                new_recommended_actions = Some(self.recalculate_recommended_actions()?);
            }
            _ => {
                return Err(BatchReconciliationError::OperationNotImplemented {
                    operation: *operation,
                }.into());
            }
        }

        info!(
            "Reconciliation operation {:?} for batch {:?} completed successfully",
            operation,
            self.index()
        );

        Ok(new_recommended_actions)
    }
}

impl BatchFileReconciliationRecommendedCourseOfAction {
    pub fn steps(&self) -> &[BatchFileTripleReconciliationOperation] {
        &self.steps
    }
}

impl From<Vec<BatchFileTripleReconciliationOperation>> for BatchFileReconciliationRecommendedCourseOfAction {
    fn from(steps: Vec<BatchFileTripleReconciliationOperation>) -> Self {
        Self { steps }
    }
}

impl TryFrom<&BatchFileTriple> for BatchFileReconciliationRecommendedCourseOfAction {
    type Error = BatchReconciliationError;
    fn try_from(triple: &BatchFileTriple) -> Result<BatchFileReconciliationRecommendedCourseOfAction, BatchReconciliationError> {
        if triple.all_are_none() {
            return Err(BatchWorkspaceError::NoBatchFileTripleAtIndex {
                index: triple.index().clone(),
            }.into());
        }

        if triple.input().is_none() {
            return Err(BatchReconciliationError::MissingBatchInputFileButOthersExist {
                index: triple.index().clone(),
                output: triple.output().clone(),
                error: triple.error().clone(),
            });
        }

        use BatchFileTripleReconciliationOperation::*;
        let steps = match BatchFileState::from(triple) {
            BatchFileState::InputOutputError => {
                warn!("Both output and error files are present for batch {:?}", triple.index());
                vec![
                    EnsureInputRequestIdsMatchOutputRequestIdsCombinedWithErrorRequestIds,
                    ProcessBatchErrorFile,
                    ProcessBatchOutputFile,
                    MoveBatchTripleToTheDoneDirectory,
                ]
            }
            BatchFileState::InputOutput => {
                vec![
                    EnsureInputRequestIdsMatchOutputRequestIds,
                    ProcessBatchOutputFile,
                    MoveBatchInputAndOutputToTheDoneDirectory,
                ]
            }
            BatchFileState::InputError => {
                warn!("Error file present but no output file for batch {:?}", triple.index());
                vec![
                    EnsureInputRequestIdsMatchErrorRequestIds,
                    ProcessBatchErrorFile,
                    MoveBatchInputAndErrorToTheDoneDirectory,
                ]

            }
            BatchFileState::InputOnly => {
                warn!("Neither output nor error files are present for batch {:?}", triple.index());
                vec![
                    CheckForBatchOutputAndErrorFileOnline,
                    RecalculateRecommendedCourseOfActionIfTripleChanged,
                ]
            }
        };

        Ok(BatchFileReconciliationRecommendedCourseOfAction::from(steps))
    }
}

impl RecalculateRecommendedActions for BatchFileTriple {
    fn recalculate_recommended_actions(&self) -> Result<BatchFileReconciliationRecommendedCourseOfAction, BatchReconciliationError> {
        // Re-run the logic to determine the next steps based on the updated triple
        BatchFileReconciliationRecommendedCourseOfAction::try_from(self)
    }
}

impl<E> ReconcileUnprocessed<E> for BatchFileTriple where E : From<BatchReconciliationError> + From<BatchDownloadError> + From<BatchErrorProcessingError> + From<BatchMetadataError> + From<BatchOutputProcessingError> + From<BatchValidationError> + From<FileMoveError> + From<OpenAIClientError> + From<std::io::Error> + Debug + Send + Sync {
    async fn reconcile_unprocessed(&mut self, client: &dyn LanguageModelClientInterface<E>, expected_content_type: &ExpectedContentType, process_output_file_fn: &BatchWorkflowProcessOutputFileFn, process_error_file_fn: &BatchWorkflowProcessErrorFileFn) -> Result<(), E> {
        info!("Attempting to reconcile unprocessed batch triple {:?}", self.index());

        let actions = BatchFileReconciliationRecommendedCourseOfAction::try_from(&*self);
        if let Err(e) = actions {
            error!("Error determining actions for batch {:?}: {:?}", self.index(), e);
            return Ok(());
        }

        let mut actions = actions.unwrap();
        info!(
            "Reconciliation actions for batch triple {:?}: {:#?}",
            self.index(),
            actions
        );

        loop {
            let steps = actions.steps();
            let mut hit_error       = false;
            let mut errors          = vec![];
            let mut updated_actions = false;

            'steps: for action in steps {
                debug!("Performing reconciliation step: {:?}", action);

                match self.execute_reconciliation_operation(
                    client,
                    action,
                    expected_content_type,
                    process_output_file_fn,
                    process_error_file_fn
                ).await {
                    Ok(Some(new_actions)) => {
                        if actions != new_actions {
                            actions = new_actions;
                            updated_actions = true;
                            debug!("Actions changed; recalculating steps");
                            break 'steps;
                        }
                    },
                    Ok(None) => {
                        trace!("No follow-up actions from step {:?}", action);
                    },
                    Err(e) => {
                        hit_error = true;
                        error!(
                            "Error applying batch action {:?} to reconcile batch {:?}: {:?}",
                            action,
                            self.index(),
                            e
                        );
                        errors.push((action.clone(), e));
                    }
                }
            }

            if updated_actions {
                // If new actions got returned, we handle them in the next iteration.
                continue;
            }

            if !hit_error {
                info!(
                    "Successfully reconciled batch triple {:?} with final actions {:#?}",
                    self.index(),
                    actions
                );
                return Ok(());
            } else {
                error!("Failed to reconcile batch triple {:?} due to errors.", self.index());
                for error in errors {
                    error!("{:#?}",error);
                }
                return Err(BatchReconciliationError::ReconciliationFailed {
                    index:  self.index().clone(),
                }.into());
            }
        }
    }
}

