/// A trait that describes the system message goal for a given axis set.
/// This is typically implemented for the entire enum and returns a single,
/// static system message goal string for the entire type.
pub trait SystemMessageGoal {
    fn system_message_goal(&self) -> Cow<'_,str>;
}


pub trait GetTokenExpansionAxes {
    fn axes(&self) -> TokenExpansionAxes;
}


/// This trait we use as a generic expander of tokens. It leverages a collection of
/// TokenExpanderAxes and has its implementation typically automatically generated by the
/// TokenExpansionAxis proc macro
pub trait TokenExpander {}


/// This trait marks types which represent expanded tokens.
/// It is helpful to have a way to treat them generically
pub trait ExpandedToken {
    /// which type of expander produced this token?
        type Expander: TokenExpander;
}


pub trait GetSystemMessageAtAgentCoordinate {
    fn get_system_message_at_agent_coordinate(&self, coord: &AgentCoordinate) -> String;
}


pub trait CreateLanguageModelRequestsAtAgentCoordinate {
    fn create_language_model_requests_at_agent_coordinate<X:IntoLanguageModelQueryString>(&self, model: &LanguageModelType, coord: &AgentCoordinate, inputs: &[X]) -> Vec<LanguageModelBatchAPIRequest>;
}

pub type TokenExpansionAxes = Vec<Arc<dyn TokenExpansionAxis>>;

impl IntoLanguageModelQueryString for CamelCaseTokenWithComment {
    fn into_language_model_query_string(&self) -> String {
        self.clone().into()
    }
}

impl<T: TokenExpander> GetSystemMessageAtAgentCoordinate for T {
    fn get_system_message_at_agent_coordinate(&self, coord: &AgentCoordinate) -> String {

        let llm = InstructedLanguageModelAtCoordinate::emit_detailed_json_objects(coord);

        let steps = TokenExpansionStep::vec_from_axes(&self.axes());

        let message_header = SystemMessageHeader::from(&llm).get();

        const GLOBAL_INSTRUCTIONS: &'static str 
            = "Convert the provided token into a JSON representation, restructured according to the specified axes. 
            Follow these steps meticulously to ensure consistency and completeness:";

        let mut system_message = format!{
            "{}\n\nInstructions:\n\n{}\n\n", 
            message_header, 
            GLOBAL_INSTRUCTIONS
        };

        for (i, step) in steps.iter().enumerate() {
            system_message.push_str(&format!("Step {}: {}\n\n{}", i + 1, step.name(), step.ai_instructions()));
        }

        system_message
    }
}

impl<T:GetSystemMessageAtAgentCoordinate> CreateLanguageModelRequestsAtAgentCoordinate for T {
    fn create_language_model_requests_at_agent_coordinate<X:IntoLanguageModelQueryString>(&self, model: &LanguageModelType, coord: &AgentCoordinate, inputs: &[X]) -> Vec<LanguageModelBatchAPIRequest> {
        let system_message = self.get_system_message_at_agent_coordinate(coord);

        let queries: Vec<String> = inputs.iter().map(|tok| tok.into_language_model_query_string()).collect();

        LanguageModelBatchAPIRequest::requests_from_query_strings(&system_message,model.clone(),&queries)
    }
}

