/// A wrapper for a comma-separated list of expressions.
#[derive(Getters,Debug)]
#[getset(get="pub")]
pub struct CommaSeparatedExpressions {
    expressions: Punctuated<Expr, Token![,]>,
}

pub fn gather_doc_comments(attrs: &[Attribute]) -> Vec<String> {
    info!("Starting gather_doc_comments on {} attributes", attrs.len());
    let mut lines = Vec::new();

    for attr in attrs {
        trace!("Examining attribute: {:?}", attr);

        // We only care about `#[doc(...)]` or `#[doc = ...]`.
        if !attr.path().is_ident("doc") {
            debug!("Skipping non-doc attribute");
            continue;
        }

        match &attr.meta {
            // `#[doc = "some doc line"]`
            Meta::NameValue(MetaNameValue {
                value: Expr::Lit(ExprLit { lit: Lit::Str(s), .. }),
                ..
            }) => {
                debug!("Found name-value doc attribute => {:?}", s.value());
                lines.push(s.value());
            }

            // Fallback for NameValue doc attributes that don't match the literal string pattern.
            Meta::NameValue(other) => {
                warn!("Unhandled name-value doc attribute format: {:?}", other);
            }

            // `#[doc(...)]` => Could be e.g. doc("some doc") or doc(one="1", two("2")) etc.
            Meta::List(MetaList { tokens, .. }) => {
                trace!("Found list style doc => parsing comma-separated expressions");
                match parse2::<CommaSeparatedExpressions>(tokens.clone()) {
                    Ok(cse) => {
                        for expr in cse.expressions() {
                            parse_doc_expr(&expr, &mut lines);
                        }
                    }
                    Err(e) => {
                        warn!("Failed parsing doc(...) tokens as expressions: {:?}", e);
                    }
                }
            }

            // Just `#[doc]` (no tokens) => skip
            Meta::Path(_) => {
                trace!("Found bare path doc => ignoring");
            }
        }
    }

    trace!("Completed gather_doc_comments with lines: {:?}", lines);
    lines
}


#[proc_macro_derive(AiJsonTemplate)]
pub fn derive_ai_json_template(input: TokenStream) -> TokenStream {
    trace!("Entering derive_ai_json_template macro.");

    let ast = parse_macro_input!(input as DeriveInput);
    let struct_ident = &ast.ident;
    let struct_span  = ast.span();
    let struct_name_str = struct_ident.to_string();
    trace!("Processing struct: {}", struct_name_str);

    // Gather doc comments from the struct itself
    let struct_docs_vec = gather_doc_comments(&ast.attrs);
    let struct_docs_str = struct_docs_vec.join("\n");
    trace!("Gathered struct doc comments = {:?}", struct_docs_vec);

    let fields = match &ast.data {
        Data::Struct(DataStruct { fields: Fields::Named(named), .. }) => {
            trace!("Struct has named fields.");
            &named.named
        },
        _ => {
            let err = syn::Error::new(
                struct_span,
                "AiJsonTemplate derive only supports a named struct."
            );
            return err.to_compile_error().into();
        }
    };

    let mut field_inits = Vec::new();
    for field in fields {
        let field_ident = match &field.ident {
            Some(id) => id,
            None => {
                let err = syn::Error::new(
                    field.span(),
                    "Unnamed fields are not supported by AiJsonTemplate."
                );
                return err.to_compile_error().into();
            }
        };
        let field_name_str = field_ident.to_string();
        trace!("Analyzing field: {}", field_name_str);

        // doc comments for the field
        let field_docs = gather_doc_comments(&field.attrs).join("\n");
        trace!("Field docs => {:?}", field_docs);

        let ty = &field.ty;
        let type_q = quote!(#ty).to_string();
        trace!("Field type => {}", type_q);

        if let Some(expr) = classify_field_type(ty, &field_docs) {
            field_inits.push(quote! {
                map.insert(#field_name_str.to_string(), #expr);
            });
        } else {
            let err_msg = format!("Unsupported field type for AiJsonTemplate: {}", type_q);
            trace!("ERROR: {}", err_msg);
            let err = syn::Error::new(ty.span(), err_msg);
            return err.to_compile_error().into();
        }
    }

    let expanded = quote! {
        impl AiJsonTemplate for #struct_ident {
            fn to_template() -> serde_json::Value {
                tracing::trace!("AiJsonTemplate::to_template for struct {}", #struct_name_str);

                let mut root = serde_json::Map::new();
                root.insert("struct_docs".to_string(), serde_json::Value::String(#struct_docs_str.to_string()));
                root.insert("struct_name".to_string(), serde_json::Value::String(#struct_name_str.to_string()));

                let mut map = serde_json::Map::new();
                #(#field_inits)*

                root.insert("fields".to_string(), serde_json::Value::Object(map));
                serde_json::Value::Object(root)
            }
        }
    };

    trace!("Exiting derive_ai_json_template macro for {}", struct_name_str);
    expanded.into()
}


pub fn classify_field_type(ty: &syn::Type, doc_str: &str) -> Option<proc_macro2::TokenStream> {
    trace!("classify_field_type => doc_str={:?}, ty=?", doc_str);
    let ty_str = quote!(#ty).to_string().replace(' ', "");
    let doc_lit = proc_macro2::Literal::string(doc_str);

    match ty_str.as_str() {
        "String" => {
            trace!("Field is a String. Required = true");
            Some(quote! {
                {
                    let mut obj = serde_json::Map::new();
                    obj.insert("type".to_string(), serde_json::Value::String("string".to_string()));
                    obj.insert("generation_instructions".to_string(), serde_json::Value::String(#doc_lit.trim().to_string()));
                    obj.insert("required".to_string(), serde_json::Value::Bool(true));
                    serde_json::Value::Object(obj)
                }
            })
        },
        "Vec<String>" => {
            trace!("Field is a Vec<String>. Required = true");
            Some(quote! {
                {
                    let mut obj = serde_json::Map::new();
                    obj.insert("type".to_string(), serde_json::Value::String("array_of_strings".to_string()));
                    obj.insert("generation_instructions".to_string(), serde_json::Value::String(#doc_lit.trim().to_string()));
                    obj.insert("required".to_string(), serde_json::Value::Bool(true));
                    serde_json::Value::Object(obj)
                }
            })
        },
        "Option<String>" => {
            trace!("Field is an Option<String>. Required = false");
            Some(quote! {
                {
                    let mut obj = serde_json::Map::new();
                    obj.insert("type".to_string(), serde_json::Value::String("string".to_string()));
                    obj.insert("generation_instructions".to_string(), serde_json::Value::String(#doc_lit.trim().to_string()));
                    obj.insert("required".to_string(), serde_json::Value::Bool(false));
                    serde_json::Value::Object(obj)
                }
            })
        },
        _ => {
            // assume it's a nested struct implementing AiJsonTemplate
            trace!("Treating as nested struct => AiJsonTemplate");
            Some(quote! {
                {
                    let nested = <#ty as AiJsonTemplate>::to_template();
                    let mut obj = serde_json::Map::new();
                    obj.insert("type".to_string(), serde_json::Value::String("nested_struct".to_string()));
                    obj.insert("generation_instructions".to_string(), serde_json::Value::String(#doc_lit.trim().to_string()));
                    obj.insert("required".to_string(), serde_json::Value::Bool(true));
                    obj.insert("nested_template".to_string(), nested);
                    serde_json::Value::Object(obj)
                }
            })
        }
    }
}

impl Parse for CommaSeparatedExpressions {
    fn parse(input: ParseStream) -> syn::Result<Self> {
        trace!("Starting to parse comma-separated expressions.");
