}

pub async fn parse_token_file(filename: &str) -> Result<Vec<CamelCaseTokenWithComment>, TokenParseError> {
    info!("parsing token file {}", filename);

    let file = File::open(filename).await?;
    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    let mut tokens = Vec::new();

    while let Some(line) = lines.next_line().await? {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        match line.parse::<CamelCaseTokenWithComment>() {
            Ok(token) => tokens.push(token),
            Err(e) => {
                warn!("{:?}", e);
            }
        }
    }

    Ok(tokens)
}


/// Extracts the "token_name" field from a JSON object.
///
/// # Arguments
/// * `json` - A reference to a `serde_json::Value` object.
/// # Returns
/// * `Result<&str, TokenParseError>` - The token name as a string slice,
///   or an error if the field is missing or invalid.
pub fn extract_token_name_field(json: &serde_json::Value) -> Result<&str, TokenParseError> {
    json.get("token_name")
        .and_then(|tn| tn.as_str())
        .ok_or(TokenParseError::InvalidTokenName)
}

impl Named for CamelCaseTokenWithComment {
    fn name(&self) -> Cow<'_,str> {
        Cow::Borrowed(&self.data)
    }
}

impl Display for CamelCaseTokenWithComment {
    fn fmt(&self, f: &mut Formatter<'_>) -> FmtResult {
        match &self.comment {
            Some(comment) => write!(f, "{} -- {}", self.data, comment),
            None => write!(f, "{}", self.data),
        }
    }
}

impl Into<String> for CamelCaseTokenWithComment {
    fn into(self) -> String {
        match self.comment {
            Some(ref comment) => format!("{} -- {}", self.data, comment),
            None              => format!("{}", self.data),
        }
    }
}

impl std::str::FromStr for CamelCaseTokenWithComment {
    type Err = TokenParseError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let line = s.trim();
        if line.is_empty() {
            return Err(TokenParseError::InvalidTokenLine(line.to_string()));
        }

        let parts: Vec<&str> = line.splitn(2, "--").collect();
        let data = parts[0].trim();
        if data.is_empty() {
            return Err(TokenParseError::InvalidTokenLine(line.to_string()));
        }

        let comment = parts.get(1).map(|&s| s.trim().to_string()).filter(|s| !s.is_empty());

        Ok(CamelCaseTokenWithComment {
            data: data.to_string(),
            comment,
        })
    }
}

