impl<T> LocateBatchFiles for T where for<'async_trait> T: BatchWorkspaceInterface + Send + Sync + 'async_trait {
    type Error = BatchWorkspaceError;
    async fn locate_batch_files(self, index: &BatchIndex) -> Result<Option<BatchFileTriple>, Self::Error> {
        trace!("attempting to locate batch files for index: {:?}", index);

        // Get the regex pattern for the specified index to match filenames
        let file_pattern = index.file_pattern();

        let mut input               = None;
        let mut output              = None;
        let mut error               = None;
        let mut associated_metadata = None;

        let mut entries = fs::read_dir(self.workdir()).await?;

        while let Some(entry) = entries.next_entry().await? {
            let path = entry.path();

            // Get filename as a &str
            let filename = match path.file_name().and_then(|name| name.to_str()) {
                Some(name) => name,
                None => {
                    trace!("skipping a file with non-UTF8 name: {:?}", path);
                    continue;
                }
            };

            // Use the precompiled regex pattern to match filenames
            let captures = match file_pattern.captures(filename) {
                Some(captures) => captures,
                None => {
                    debug!("filename does not match the expected pattern: {:?}", filename);
                    continue;
                }
            };

            // Extract the type of the file from the capture group
            let file_type = captures.get(1).map(|m| m.as_str());

            match file_type {
                Some("input") => {
                    if input.is_some() {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "Multiple input files found"
                        ).into());
                    }
                    debug!("found input file: {:?}", path);
                    input = Some(path);
                }
                Some("output") => {
                    if output.is_some() {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "Multiple output files found"
                        ).into());
                    }
                    debug!("found output file: {:?}", path);
                    output = Some(path);
                }
                Some("error") => {
                    if error.is_some() {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "Multiple error files found"
                        ).into());
                    }
                    debug!("found error file: {:?}", path);
                    error = Some(path);
                }
                Some("metadata") => {
                    if associated_metadata.is_some() {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "Multiple associated_metadata files found"
                        ).into());
                    }
                    debug!("found associated_metadata file: {:?}", path);
                    associated_metadata = Some(path);
                }
                _ => {
                    trace!("skipping unrecognized file type: {:?}", filename);
                    continue;
                }
            }
        }

        if input.is_none() && output.is_none() && error.is_none() && associated_metadata.is_none() {
            debug!("no batch files found in directory for index {:?}: {:?}", index, self.workdir());
            Ok(None)
        } else {
            debug!(
                "batch files located for index {:?} - input: {:?}, output: {:?}, error: {:?}, metadata: {:?}",
                index, input, output, error, associated_metadata
            );
            Ok(Some(BatchFileTriple::new_direct(
                        index, 
                        input, 
                        output, 
                        error, 
                        associated_metadata, 
                        self.clone()
            )))
        }
    }
}

impl<T: GetTargetPathForAIExpansion + Clone + Display + Named> CalculateUnseenInputs<T> for BatchWorkspace {
    /// Internal helper. Identifies newly seen tokens.
    fn calculate_unseen_inputs(&self, inputs: &[T], expected_content_type: &ExpectedContentType) -> Vec<T> {

        let target_dir = self.target_dir();

        let mut unseen: Vec<T> = Vec::new();

        for tok in inputs {

            let target_path = tok.target_path_for_ai_json_expansion(
                &target_dir,
                expected_content_type
            );

            if !target_path.exists() {

                if let Some(similar_path) = self.find_similar_target_path(&target_path) {

                    warn!(
                        "Skipping token '{}': target path '{}' is similar to existing '{}'.",
                        tok.name(),
                        target_path.display(),
                        similar_path.display()
                    );

                    // Skip this token
                    continue;
                }

                unseen.push(tok.clone());
            }
        }

        info!("Unseen input tokens calculated:");

        for token in &unseen {
            info!("{}", token);
        }

        unseen
    }
}

impl<T> FindExistingBatchFileIndices for T where for<'async_trait> T: BatchWorkspaceInterface + Send + Sync + 'async_trait {
    type Error = BatchWorkspaceError;
    async fn find_existing_batch_file_indices(self) -> Result<HashSet<BatchIndex>, Self::Error> {
        trace!("scanning directory to find existing batch file indices");

        let workdir = self.workdir();
        let file_pattern = Regex::new(r"batch_(input|output|error)_(\d+|[a-f0-9\-]{36})\.jsonl$")
            .expect("invalid regex pattern in find_existing_batch_file_indices");

        let mut indices = HashSet::new();
        let mut dir_entries = fs::read_dir(workdir).await?;

        while let Some(entry) = dir_entries.next_entry().await? {
            let path = entry.path();

            if let Some(filename) = path.file_name().and_then(|name| name.to_str()) {
                if let Some(captures) = file_pattern.captures(filename) {
                    if let Some(index_match) = captures.get(2) {
                        let index_str = index_match.as_str();
                        let index = if let Ok(num) = index_str.parse::<usize>() {
                            BatchIndex::Usize(num)
                        } else {
                            BatchIndex::from_uuid_str(index_str)?
                        };
                        trace!("found matching batch index: {:?}", index);
                        indices.insert(index);
                    }
                }
            }
        }

        debug!("collected batch indices: {:?}", indices);
        Ok(indices)
    }
}

