impl From<&BatchFileTriple> for BatchFileState {
    /// Determines the state of the batch files.
    fn from(triple: &BatchFileTriple) -> BatchFileState {

        let has_input  = triple.input().is_some();
        let has_error  = triple.error().is_some();
        let has_output = triple.output().is_some();

        match (has_input, has_output, has_error) {
            (true, true, true)   => BatchFileState::InputOutputError,
            (true, true, false)  => BatchFileState::InputOutput,
            (true, false, true)  => BatchFileState::InputError,
            (true, false, false) => BatchFileState::InputOnly,
            _ => unreachable!("Input file must be present at this point"),
        }
    }
}

impl BatchFileTriple {
    pub async fn ensure_input_matches_output(&self) -> Result<(), BatchValidationError> {
        // Load input and output files
        let input_data  = load_input_file(self.input().as_ref().unwrap()).await?;

        let output_data = load_output_file(self.output().as_ref().unwrap()).await?;

        // Compare request IDs
        let input_ids:  HashSet<_> = input_data.request_ids().into_iter().collect();

        let output_ids: HashSet<_> = output_data.request_ids().into_iter().collect();

        if input_ids != output_ids {
            return Err(BatchValidationError::RequestIdsMismatch {
                index:      self.index().clone(),
                input_ids:  Some(input_ids),
                output_ids: Some(output_ids),
                error_ids:  None,
            });
        }

        info!("for our batch triple {:#?}, we have now ensured the input request ids match the request ids from the output file",self);

        Ok(())
    }
}

