pub async fn process_output_data<T>(output_data: &BatchOutputData, workspace: &dyn BatchWorkspaceInterface, expected_content_type: &ExpectedContentType) -> Result<(), BatchOutputProcessingError> where
    // `'static + Send + Sync` ensures T can be held in `Arc<dyn ... + Send + Sync + 'static>`,
