        info!("downloading batch error file");

        if self.error().is_some() {
            return Err(BatchDownloadError::ErrorFileAlreadyExists {
                triple: self.clone(),
            }
            .into());
        }

        let metadata_filename = self.metadata_filename_which_maybe_does_not_yet_exist();
        let metadata = BatchMetadata::load_from_file(&metadata_filename).await?;
        let error_file_id = metadata.error_file_id()?;

        let file_content = client.file_content(error_file_id).await?;

        let error_path = self.error_filename_which_maybe_does_not_yet_exist();
        assert!(!error_path.exists());

        std::fs::write(&error_path, file_content)?;

        self.set_error_path(Some(error_path));
        Ok(())
    }
}

impl<E> CheckForAndDownloadOutputAndErrorOnline<E> for BatchFileTriple where E: From<BatchDownloadError> + From<OpenAIClientError> + From<BatchMetadataError> + From<std::io::Error> {
    async fn check_for_and_download_output_and_error_online(&mut self, client: &dyn LanguageModelClientInterface<E>) -> Result<(), E> {
        info!("Checking for and downloading output/error files if available.");

        // Just call check_batch_status_online:
        // If we are incomplete, or have a failure, that function returns an error.
        let status = self.check_batch_status_online(client).await?;

        // If completed, let's download whichever are available:
        info!("batch online status: {:?}", status);

        if status.output_file_available() {
            self.download_output_file(client).await?;
        }
        if status.error_file_available() {
            self.download_error_file(client).await?;
        }

        Ok(())
    }
}

